def _seed_roles():
    """Roles y permisos iniciales (copia congelada de app/auth/permissions.py)."""
    permissions = [
        ("dashboard.view", "Ver el panel principal"),
        ("products.view", "Ver productos, variantes, marcas, categorías y proveedores"),
        ("products.manage", "Crear y editar productos, variantes, marcas, categorías, proveedores y fotos"),
        ("inventory.view", "Ver existencias y movimientos"),
        ("inventory.sell", "Registrar ventas y devoluciones de clientes"),
        ("inventory.move", "Registrar cualquier movimiento (entradas, ajustes, conteos físicos)"),
        ("counts.create", "Subir fotos y crear conteos inteligentes"),
        ("counts.confirm", "Confirmar conteos y conciliarlos con el stock"),
        ("imports.manage", "Importar archivos Excel/CSV"),
        ("exports.run", "Exportar datos e informes"),
        ("reports.view", "Ver reportes y BI"),
        ("orders.view", "Ver pedidos de la tienda online"),
        ("orders.manage", "Cambiar el estado de los pedidos"),
        ("users.manage", "Gestionar usuarios y roles"),
        ("audit.view", "Ver la auditoría"),
        ("settings.view", "Ver configuración y estado del sistema"),
    ]
    consulta = ["dashboard.view", "products.view", "inventory.view", "reports.view", "orders.view"]
    operador = consulta + ["inventory.sell", "counts.create", "orders.manage"]
    inventario = operador + ["products.manage", "inventory.move", "counts.confirm", "imports.manage", "exports.run"]
    roles = [
        (1, "admin", "Administrador", [p for p, _ in permissions]),
        (2, "inventario", "Encargado de inventario", inventario),
        (3, "operador", "Operador", operador),
        (4, "consulta", "Consulta", consulta),
    ]
    perm_table = sa.table("permissions", sa.column("id", sa.Integer), sa.column("code", sa.String),
                          sa.column("description", sa.String))
    role_table = sa.table("roles", sa.column("id", sa.Integer), sa.column("code", sa.String),
                          sa.column("name", sa.String))
    link_table = sa.table("role_permissions", sa.column("role_id", sa.Integer), sa.column("permission_id", sa.Integer))
    ids = {code: index for index, (code, _) in enumerate(permissions, start=1)}
    op.bulk_insert(perm_table, [{"id": ids[c], "code": c, "description": d} for c, d in permissions])
    op.bulk_insert(role_table, [{"id": i, "code": c, "name": n} for i, c, n, _ in roles])
    op.bulk_insert(link_table, [{"role_id": i, "permission_id": ids[p]} for i, _, _, perms in roles for p in perms])
    if op.get_bind().dialect.name == "postgresql":
        op.execute("SELECT setval('permissions_id_seq', (SELECT MAX(id) FROM permissions))")
        op.execute("SELECT setval('roles_id_seq', (SELECT MAX(id) FROM roles))")


